use std::path::PathBuf;
use std::process::Command;

#[test]
fn format_workspace_once_and_remove_self() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    let status = Command::new("cargo")
        .args(["fmt", "--all"])
        .current_dir(&root)
        .status()
        .expect("run cargo fmt --all");
    assert!(status.success(), "cargo fmt --all failed");
    let self_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("format_workspace.rs");
    std::fs::remove_file(self_path).expect("remove formatter harness");
}
